// ================================================================
// NODE 1: DEDUP
// n8n Code node — виконується для кожного алерту що приходить з Wazuh
//
// Призначення:
//   Відсіює дублікати алертів протягом TTL вікна (5 хвилин).
//   Wazuh може згенерувати десятки однакових алертів за секунди
//   (mimikatz відкриває LSASS в циклі, LOLBin з'єднується кожну хвилину і т.д.).
//   Без dedup pipeline і Dagobert отримували б спам замість одного інциденту.
//
// Як працює:
//   1. Для кожного алерту будується строковий ключ (buildKey)
//      що описує "цю конкретну загрозу від цього агента"
//   2. Ключ перевіряється в WorkflowStaticData (глобальний стор n8n)
//   3. Якщо ключ вже є і не прострочений → алерт кидається (return [])
//   4. Якщо новий → зберігається, алерт іде далі з полем alert.soc
//
// Вхід:  один Wazuh alert JSON (raw.body або raw)
// Вихід: [] якщо дублікат | [{ json: alert }] якщо новий
//
// ВАЖЛИВО в n8n: Always Output Data = OFF
//   (інакше n8n передає порожній об'єкт замість порожнього масиву)
//
// Verified fields: alerts_20260910_1657.json (659 events)
// ================================================================

// Час життя запису в seen-сторі: 5 хвилин
const TTL_MS = 5 * 60 * 1000;

// --- Розпаковка алерту ---
// Wazuh надсилає алерт напряму як JSON (top-level: timestamp, rule, agent...).
// n8n Webhook нода зазвичай передає його в $input.first().json без обгортки.
// Але якщо POST прийшов з Content-Type: application/x-www-form-urlencoded
// (або через деякі проксі/Logstash), n8n загортає тіло в { body: {...} }.
// raw.body ?? raw — захисний fallback: якщо body є — беремо його, інакше raw.
const raw   = $input.first().json;
const alert = raw.body ?? raw;

const rule      = alert.rule  || {};
const agent     = alert.agent || {};
const eventdata = alert.data?.win?.eventdata || {};  // Sysmon/Security eventdata (може бути відсутній)

const ruleId  = String(rule.id   || '');
const agentId = String(agent.id  || agent.name || '');  // agent.id — числовий ID, agent.name — fallback

// ----------------------------------------------------------------
// norm(v) — нормалізація поля для включення в dedup-ключ
//
// Проблема: Wazuh/Sysmon повертає шляхи і імена в різному регістрі
// залежно від версії агента і ОС. Щоб C:\Windows\lsass.exe і
// c:\windows\lsass.exe давали один і той самий ключ — приводимо
// до нижнього регістру. trim() прибирає випадкові пробіли.
//
// Backslash не чіпаємо: Sysmon завжди дає \ (не /), тому
// нормалізація роздільника не потрібна — ключ буде консистентним.
// ----------------------------------------------------------------
function norm(v) {
  return String(v || '').toLowerCase().trim();
}

// ----------------------------------------------------------------
// KEY_FIELDS — таблиця: ruleId → функція що повертає масив полів
//
// Різні rule ID детектують різні типи атак, тому і поля для ключа
// різні. Логіка відбору полів: "мінімальний набір що однозначно
// ідентифікує один інцидент протягом 5 хвилин".
//
// Щоб додати новий rule — достатньо одного рядка тут.
// Функцію buildKey() чіпати не треба.
//
// Формат ключа після join: "agentId::ruleId::field1::field2::..."
// ----------------------------------------------------------------
const KEY_FIELDS = {

  // 100820: Windows Explicit Credential Logon (Event 4648)
  //   Атакуючий явно вказує credentials для lateral movement.
  //   Один інцидент = один IP + один target user.
  //   subjectUserName — хто ініціював (може бути SYSTEM або атакуючий процес).
  '100820': e => [norm(e.ipAddress), norm(e.targetUserName), norm(e.subjectUserName)],

  // 100870: Pass-the-Hash (Event 4624, LogonType 3, NTLM)
  //   NTLM мережевий логон — класичний PtH індикатор.
  //   Унікальність: звідки прийшов логон (IP) + хто залогінився.
  '100870': e => [norm(e.ipAddress), norm(e.targetUserName), norm(e.subjectUserName)],

  // 100830: SeDebugPrivilege assigned (Event 4672)
  //   Mimikatz і більшість injectors запитують SeDebugPrivilege перед роботою.
  //   Унікальність: якому юзеру присвоєно привілей.
  '100830': e => [norm(e.subjectUserName)],

  // 100740: LSASS memory access (Sysmon Event 10 — ProcessAccess)
  //   Процес відкриває LSASS з правами читання пам'яті (credential dump).
  //   Унікальність: який процес (sourceImage) + з якими правами (grantedAccess).
  //   Без grantedAccess: один і той самий процес міг би відкрити LSASS
  //   з різними правами — це різні події.
  '100740': e => [norm(e.sourceImage), norm(e.grantedAccess)],

  // 100880: CreateRemoteThread CRITICAL (Sysmon Event 8, підозрілий source)
  // 100881: CreateRemoteThread стандартний (Sysmon Event 8)
  //   Process injection через CreateRemoteThread.
  //   Унікальність: хто інжектує (sourceImage) → в який процес (targetImage).
  '100880': e => [norm(e.sourceImage), norm(e.targetImage)],
  '100881': e => [norm(e.sourceImage), norm(e.targetImage)],

  // 100882: DLL завантажена з user-writable шляху (Sysmon Event 7 — ImageLoad)
  //   DLL hijacking або malware що дропнув DLL в AppData/Temp/Downloads.
  //   Унікальність: який процес завантажив підозрілу DLL.
  '100882': e => [norm(e.image)],

  // 100883: DLL з невалідним або відсутнім підписом (Sysmon Event 7)
  //   ~895 алертів/день на продакшені — без dedup заспамив би pipeline.
  //   Унікальність: який процес завантажив непідписану DLL.
  '100883': e => [norm(e.image)],

  // 100884: LOLBin завантажує підозрілу DLL (Sysmon Event 7)
  //   Легітимний системний бінарник (rundll32, regsvr32, mshta...)
  //   використовується для завантаження шкідливого коду.
  '100884': e => [norm(e.image)],

  // 100825: LOLBin initiated outbound connection (Sysmon Event 3)
  //   Системний бінарник з'єднується назовні — C2 індикатор.
  // 100826: Outbound connection з підозрілої директорії (Sysmon Event 3)
  //   Процес з Temp/AppData/Downloads з'єднується назовні.
  //   Обидва: unікальність = який процес робить з'єднання.
  '100825': e => [norm(e.image)],
  '100826': e => [norm(e.image)],

  // 100743: Persistence mechanism (Run key / Startup folder modified)
  //   КОЖНА зміна Run key — окремий факт що треба розслідувати.
  //   Дедуплікація заборонена: використовуємо унікальний alert ID.
  //   Date.now() — останній fallback якщо Wazuh не передав ID.
  '100743': _e => [alert.id || alert.alert_id || String(Date.now())],
};

// ----------------------------------------------------------------
// buildKey() — будує рядковий dedup-ключ для поточного алерту
//
// Структура ключа: "agentId::ruleId::field1::field2::..."
//   agentId — прив'язує ключ до конкретного хоста
//   ruleId  — тип загрози
//   fields  — що саме сталось (залежить від типу загрози)
//
// Fallback (rule не в KEY_FIELDS):
//   image + commandLine — підходить для більшості process-based rules
//   що не потребують спеціальної логіки.
// ----------------------------------------------------------------
function buildKey() {
  const base   = `${agentId}::${ruleId}`;
  const schema = KEY_FIELDS[ruleId];

  if (schema) return [base, ...schema(eventdata)].join('::');

  return [base, norm(eventdata.image), norm(eventdata.commandLine)].join('::');
}

// ================================================================
// Dedup logic
// ================================================================

const key = buildKey();

// $getWorkflowStaticData('global') — персистентний стор n8n
// Живе поки запущений workflow. store.dedup = { key: timestamp, ... }
const store = $getWorkflowStaticData('global');
const seen  = store.dedup || {};
const now   = Date.now();

// Очищення прострочених записів (TTL = 5 хвилин)
// Без цього seen росте необмежено і з часом уповільнює ноду
for (const k of Object.keys(seen)) {
  if (now - seen[k] > TTL_MS) delete seen[k];
}

// Якщо ключ вже бачили — дублікат, кидаємо алерт
if (seen[key]) { store.dedup = seen; return []; }

// Новий алерт — зберігаємо ключ і пропускаємо далі
seen[key] = now;
store.dedup = seen;

// Додаємо мета-поле для діагностики і наступних нод pipeline
alert.soc = {
  dedup_key:    key,   // для debug і логування
  dedup_ttl_s:  300,   // скільки секунд цей ключ активний
  dedup_status: 'NEW', // наступні ноди можуть перевірити статус
};

return [{ json: alert }];

// ================================================================
// NODE 2: FP CLASSIFIER
// Вся FP логіка керується через Dagobert UI (/fp-rules/).
// Ця нода: захист NEVER_DROP + динамічні правила Dagobert + PASS.
// Жодної жорсткої per-rule логіки тут — нові паттерни додавати через Dagobert.
// ВАЖЛИВО: Always Output Data = OFF
// ================================================================

const alert     = $('DEDUP').first().json;
const rule      = alert.rule  || {};
const eventdata = alert.data?.win?.eventdata || {};
const syscheck  = alert.data?.syscheck || alert.alert?.full_alert?.syscheck || {};

const ruleId = String(rule.id    || '');
const level  = Number(rule.level || 0);

function norm(v) { return String(v || '').toLowerCase().replace(/\//g, '\\').trim(); }

// FP правила з Dagobert API (нода Get FP Rules передає дані в цю ноду)
const _dynRules = $input.all().map(i => i.json).filter(r => r && r.field);

// Карта полів: назва поля Dagobert → нормалізоване значення події
const _fieldMap = {
  image:             norm(eventdata.image              || ''),
  commandLine:       norm(eventdata.commandLine        || ''),
  sourceImage:       norm(eventdata.sourceImage        || ''),
  targetImage:       norm(eventdata.targetImage        || ''),
  imageLoaded:       norm(eventdata.imageLoaded        || ''),
  parentImage:       norm(eventdata.parentImage        || ''),
  parentCommandLine: norm(eventdata.parentCommandLine  || ''),
  startModule:       norm(eventdata.startModule        || ''),
  startFunction:     norm(eventdata.startFunction      || ''),
  subjectUserName:   norm(eventdata.subjectUserName    || ''),
  targetUserName:    norm(eventdata.targetUserName     || ''),
  targetDomainName:  norm(eventdata.targetDomainName   || ''),
  grantedAccess:     norm(eventdata.grantedAccess      || ''),
  destinationIp:     norm(eventdata.destinationIp      || ''),
  destinationPort:   norm(eventdata.destinationPort    || ''),
  ipAddress:         norm(eventdata.ipAddress          || ''),
  workstationName:   norm(eventdata.workstationName    || ''),
  targetServerName:  norm(eventdata.targetServerName   || ''),
  callTrace:         norm(eventdata.callTrace          || ''),
  signatureStatus:   norm(eventdata.signatureStatus    || ''),
  registryPath:      norm(syscheck.path                || ''),
  filePath:          norm(syscheck.path                || ''),
  agentName:         norm(alert.agent?.name            || ''),
  agentIp:           norm(alert.agent?.ip              || ''),
};

// Правила що НІКОЛИ не можна авто-дропати як FP — примусово FP_CANDIDATE
const NEVER_DROP = new Set([
  '100740','100741','100742','100744',
  '100730','100731',
  '100743',
  '100750',
  '100780','100782','100783','100786','100787',
  '100795','100796','100798','100799',
  '100824',
  '100841','100842','100843',
  '100880',
]);

function classify() {
  for (const r of _dynRules) {
    if (r.rule_ids && r.rule_ids.length && !r.rule_ids.includes(ruleId)) continue;
    const val   = _fieldMap[r.field] || '';
    const check = (r.value || '').toLowerCase();
    let match = false;
    if      (r.op === 'includes')   match = val.includes(check);
    else if (r.op === 'endsWith')   match = val.endsWith(check);
    else if (r.op === 'startsWith') match = val.startsWith(check);
    else if (r.op === 'equals')     match = val === check;
    else if (r.op === 'regex')      match = new RegExp(r.value, 'i').test(val);
    if (match) return { status: r.status || 'FP', reason: '[dyn] ' + (r.reason || r.field + ' ' + r.op + ' ' + r.value) };
  }
  return { status: 'PASS', reason: '' };
}

const result = classify();

if (NEVER_DROP.has(ruleId) && result.status === 'FP') {
  result.status = 'FP_CANDIDATE';
  result.reason = '[NEVER_DROP] ' + result.reason;
}

alert.soc = {
  ...(alert.soc || {}),
  fp_status:          result.status,
  fp_reason:          result.reason,
  requires_ai_review: result.status !== 'FP',
};

if (result.status === 'FP') {
  try {
    const fs = require('fs'), path = require('path');
    const dir = '/home/node/.n8n/fp-journal';
    fs.mkdirSync(dir, { recursive: true });
    fs.appendFileSync(
      path.join(dir, 'fp_journal.jsonl'),
      JSON.stringify({ ts: new Date().toISOString(), source: 'n8n_node2', rule_id: ruleId, level, agent: alert.agent?.name || '', fp_reason: result.reason }) + '\n'
    );

  } catch(e) {}
  return [];
}
return [{ json: alert }];

// ================================================================
// NODE 3: NORMALIZE ALERT
// ================================================================
//
// Призначення:
//   Розпаковує alert після DEDUP і будує плоску структуру з
//   усіма ключовими полями на верхньому рівні. Наступні ноди
//   (Find Existing Case, Build Payloads) читають звідси — не з
//   вкладеного alert.rule.id, а просто d.ruleId.
//
// Вхід:
//   DEDUP → { timestamp, rule, agent, data, soc, ... }
//
// Вихід (плоска структура):
//   alert      — повний оригінальний об'єкт алерту
//   agent      — { id, name, ip }
//   rule       — { id, level, description, groups, mitre }
//   data       — { win: { eventdata, system }, syscheck, ... }
//   soc        — { dedup_key, fp_status, fp_reason, ... }
//   corrKey    — ключ кореляції: agent.ip або agent.id або agent.name
//                (використовується для пошуку/створення кейсу в Dagobert)
//   alertId    — унікальний ID алерту від Wazuh
//   timestamp  — час події
//   ruleId     — String (щоб порівнювати без Number/String плутанини)
//   ruleLevel  — Number
//   agentName  — ім'я хоста
//   agentIp    — IP агента
//   fpStatus   — PASS | FP | FP_CANDIDATE
//   fpReason   — пояснення від FP Classifier
//
// ================================================================

const alert = $input.first().json;

const agent = alert.agent || {};
const rule  = alert.rule  || {};
const data  = alert.data  || {};
const soc   = alert.soc   || {};

const corrKey = agent.ip || agent.id || agent.name;

return [{ json: {
  alert,
  agent,
  rule,
  data,
  soc,
  corrKey,
  alertId:   alert.id || alert.alert_id || '',
  timestamp: alert.timestamp || new Date().toISOString(),
  ruleId:    String(rule.id    || ''),
  ruleLevel: Number(rule.level || 0),
  agentName: agent.name || 'unknown',
  agentIp:   agent.ip   || '',
  fpStatus:  soc.fp_status || 'PASS',
  fpReason:  soc.fp_reason || '',
} }];

// ================================================================
// NODE 4: FIND EXISTING CASE
// ================================================================
//
// Призначення:
//   Визначає чи існує вже відкритий кейс у Dagobert для цього хоста.
//   Якщо є — повертає його ID і Name → іде гілка "Update".
//   Якщо немає — повертає порожній existingCaseId → іде гілка "Create".
//
// Логіка пошуку кейсу:
//   1. Спочатку перевіряємо WorkflowStaticData (in-memory cache):
//      caseCache[corrKey] = { id, name, ts }
//      TTL кешу = 4 години. Якщо запис є і не прострочений — не
//      звертаємось до Dagobert API зайвий раз.
//   2. Якщо в кеші немає — шукаємо в списку кейсів від попередньої
//      HTTP ноди (GET /cases): відкритий кейс з назвою [HOST] що
//      містить corrKey (IP агента).
//
// corrKey:
//   agent.ip → основний ключ кореляції.
//   Всі алерти від одного хоста (IP) → один кейс у Dagobert.
//   Назва кейсу: "[HOST] <agentName> (<agentIp>)"
//
// Вхід:
//   Normalize Alert → { corrKey, agentName, agentIp, ruleId, ... }
//   HTTP GET /cases → масив кейсів { ID, Name, Closed, ... }
//
// Вихід:
//   { ...всі поля з Normalize, existingCaseId, existingCaseName }
//   existingCaseId = '' → гілка Create New Case
//   existingCaseId = 'XxXxX' → гілка Update Existing Case
//
// ================================================================

const d       = $('Normalize Alert').first().json;
const corrKey = d.corrKey;

// ── Cache lookup ──────────────────────────────────────────────────────────────
const store     = $getWorkflowStaticData('global');
const caseCache = store.caseCache || {};
const now       = Date.now();

// Прибираємо записи старші за 4 години
for (const k of Object.keys(caseCache)) {
  if (now - caseCache[k].ts > 4 * 60 * 60 * 1000) delete caseCache[k];
}
store.caseCache = caseCache;

// Якщо є в кеші — повертаємо одразу
if (caseCache[corrKey]) {
  return [{ json: {
    ...d,
    existingCaseId:   caseCache[corrKey].id,
    existingCaseName: caseCache[corrKey].name,
  } }];
}

// ── API lookup ────────────────────────────────────────────────────────────────
const raw      = $input.first().json;
const caseList = Array.isArray(raw.body) ? raw.body : [];

const existing = caseList.find(c =>
  !c.Closed &&
  typeof c.Name === 'string' &&
  c.Name.startsWith('[HOST]') &&
  c.Name.includes(corrKey)
);

return [{ json: {
  ...d,
  existingCaseId:   existing ? existing.ID   : '',
  existingCaseName: existing ? existing.Name : '',
} }];

// ================================================================
// NODE 5: BUILD UPDATE PAYLOADS
// ================================================================
//
// Призначення:
//   Гілка "існуючий кейс" — будує payload для оновлення кейсу
//   в Dagobert: додає Event, Indicator, Note і оновлює Summary.
//
// Що робить:
//   1. Event   → /cases/{id}/events/new  (form-urlencoded)
//      Тип береться з MITRE tactic алерту.
//      Raw = повний eventdata JSON без скорочень.
//   2. Note    → /cases/{id}/notes/new   (form-urlencoded)
//      Повний вміст: rule, agent, MITRE, всі eventdata поля,
//      повний Windows event message — нічого не обрізається.
//   3. Indicator → /cases/{id}/indicators/new (form-urlencoded)
//      Логіка вибору індикатора по rule ID:
//        100820/100870 → source IP (логон з зовні)
//        100825/100826 → destination IP:port (outbound C2)
//        PowerShell rules → commandLine
//        інші з image → шлях до процесу (Path)
//        fallback → опис правила
//   4. Case update → /cases/{id}  (JSON)
//      Оновлює Name, Severity, Summary з повним контекстом алерту.
//
// КРИТИЧНО: sub-endpoints потребують form-urlencoded (баг подвійного decode в Dagobert)
// POST /cases/{id} (update) використовує JSON — це НЕ sub-entity handler
//
// Вхід:  Find Existing Case → { existingCaseId, ruleId, ruleLevel, ... }
// Вихід: { eventUrl, eventForm, noteUrl, noteForm,
//           indicatorUrl, indicatorForm, caseUpdateUrl, caseUpdateJson }
//
// ================================================================

const d       = $input.first().json;
const caseId  = d.existingCaseId;
const ed      = d.data?.win?.eventdata || {};
const sys     = d.data?.win?.system    || {};
const sc      = d.data?.syscheck || d.alert?.full_alert?.syscheck || {};

const enc = encodeURIComponent;

// ── Severity ──────────────────────────────────────────────────────────────────
const sev = d.ruleLevel >= 12 ? 'High' : d.ruleLevel >= 6 ? 'Medium' : 'Low';

// ── MITRE ─────────────────────────────────────────────────────────────────────
const mitre     = d.rule.mitre || {};
const mitreIds  = mitre.id        || [];
const mitreTech = mitre.technique || [];
const mitreTac  = mitre.tactic    || [];

// Відображення Wazuh tactic (title-case) → Dagobert Event Type enum
const tacticToType = {
  'Credential Access':    'Credential Access',
  'Defense Evasion':      'Defense Evasion',
  'Discovery':            'Discovery',
  'Execution':            'Execution',
  'Exfiltration':         'Exfiltration',
  'Impact':               'Impact',
  'Initial Access':       'Initial Access',
  'Lateral Movement':     'Lateral Movement',
  'Persistence':          'Persistence',
  'Privilege Escalation': 'Privilege Escalation',
  'Reconnaissance':       'Reconnaissance',
  'Resource Development': 'Resource Development',
  'Collection':           'Collection',
  'Command and Control':  'C2',
};
const eventType = mitreTac.map(t => tacticToType[t]).find(Boolean) || 'Other';

// ── MITRE рядок для нотатки ───────────────────────────────────────────────────
const mitreStr = mitreIds.length
  ? mitreIds.map((id, i) => `${id} — ${mitreTech[i] || ''} (${mitreTac.join(', ')})`).join('\n  ')
  : 'N/A';

// ── Techniques для форми Event ────────────────────────────────────────────────
